// Development-only HTTP fixture server and real-EXE URL-loading check.
using System;using System.IO;using System.Text;using System.Net;using System.Net.Sockets;using System.Diagnostics;using System.Threading;using System.Linq;using System.Web.Script.Serialization;using SketchRust.Compat;
class HostCodesCheck {
 const string Xml="<apexSettings xmlns='urn:apex:settings'><areaCodeTable><areaCodeEntry code='' areaName='Residential'><areaCodeEntry code='HOST1' areaName='Host living' areaDescription='From desktop host' multiplier='0.75' positive='true' calculationType='LivingArea' color='255' height='9'/><areaCodeEntry code='VOID' areaName='Deduction' multiplier='0.5' positive='false' fill='65535'/></areaCodeEntry></areaCodeTable></apexSettings>";
 static int Main(string[] args){try{
  if(args[0]=="--verify-repair"){var file=ApexFile.Read(File.ReadAllBytes(args[1]));var page=ApexFile.Items(file.ToModel(),"pages").First();if(file.Pages.Sum(p=>p.Areas.Count(a=>a.Closed!=0))!=1||ApexFile.Items(page,"reopenedAreas").Any()||ApexFile.Items(page,"polygons").Count()!=1)throw new Exception("Repaired native file reopened as an unfinished draft");Console.WriteLine("PASS: repaired native boundary reopens as a closed area");return 0;}
  string root=args[1];Directory.CreateDirectory(root);var bytes=Encoding.UTF8.GetBytes(Xml);string json=HostCodes.Parse(bytes);if(!json.Contains("HOST1")||!json.Contains("#ff0000")||!json.Contains("nativeProperties"))throw new Exception("Host native XML fields lost");bool rejected=false;try{HostCodes.Parse(Encoding.UTF8.GetBytes("<!DOCTYPE a [<!ENTITY e SYSTEM 'file:///absent'>]><areaCodeTable>&e;</areaCodeTable>"));}catch(System.Xml.XmlException){rejected=true;}if(!rejected)throw new Exception("External XML entity was accepted");
  string xmlPath=Path.Combine(root,"host table.xml");File.WriteAllBytes(xmlPath,bytes);if(!HostCodes.Fetch(new Uri(xmlPath).AbsoluteUri).SequenceEqual(bytes))throw new Exception("File URL fetch failed");
  var socket=new TcpListener(IPAddress.Loopback,0);socket.Start();int port=((IPEndPoint)socket.LocalEndpoint).Port;Exception failure=null;
  var server=new Thread(delegate(){try{using(var client=socket.AcceptTcpClient())using(var stream=client.GetStream()){var request=new byte[8192];int read=stream.Read(request,0,request.Length);if(read==0)throw new Exception("No HTTP request");var header=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: application/xml\r\nContent-Length: "+bytes.Length+"\r\nConnection: close\r\n\r\n");stream.Write(header,0,header.Length);stream.Write(bytes,0,bytes.Length);}}catch(Exception e){failure=e;}});server.IsBackground=true;server.Start();
  string output=Path.Combine(root,"codes.json");var start=new ProcessStartInfo(args[0],"--check-host-codes http://127.0.0.1:"+port+"/host.xml \""+output+"\""){UseShellExecute=false,CreateNoWindow=true};using(var process=Process.Start(start)){if(!process.WaitForExit(30000)){process.Kill();throw new Exception("Native URL-loading probe timed out");}if(process.ExitCode!=0)throw new Exception("Native URL-loading probe failed");}socket.Stop();if(!server.Join(2000)||failure!=null)throw new Exception("Local HTTP fixture failed",failure);
  var table=new JavaScriptSerializer().DeserializeObject(File.ReadAllText(output)) as object[];if(table==null||table.Length!=2)throw new Exception("Native executable did not return the host code table");Console.WriteLine("PASS: nested native XML, signed factors, colors, classifications and wall defaults; external entities rejected; file URL and HTTP URL fetched by sketch EXE.");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
